@test
def test_groupby2():
    assert close(vals(gb.cumcount()), E_cumcount)
    assert close(vals(gb.cumcount(False)), E_cumcount_d)
    assert close(vals(gb.ngroup()), E_ngroup)
    assert close(fvals(gb.nth(1)) if True else [], E_nth)
    assert close(fvals(gb[["g", "h"]].shift(1)) if True else [], E_shift)
    assert close(fvals(gb[["g", "h"]].diff()) if True else [], E_diff)
    assert close(fvals(gb[["h"]].pct_change()) if True else [], E_pct)
    assert close(fvals(gb[["g", "h"]].cumsum()) if True else [], E_cumsum)
    assert close(fvals(gb[["g", "h"]].cummax()) if True else [], E_cummax)
    assert close(fvals(gb[["g", "h"]].cummin()) if True else [], E_cummin)
    assert close(fvals(gb[["g", "h"]].rank("average")) if True else [], E_rankaverage)
    assert close(fvals(gb[["g", "h"]].rank("min")) if True else [], E_rankmin)
    assert close(fvals(gb[["g", "h"]].rank("max")) if True else [], E_rankmax)
    assert close(fvals(gb[["g", "h"]].rank("first")) if True else [], E_rankfirst)
    assert close(fvals(gb[["g", "h"]].rank("dense")) if True else [], E_rankdense)
    assert close(fvals(gb[["g", "h"]].rolling(3).mean()) if True else [], E_rollmean)
    assert close(fvals(gb[["g", "h"]].rolling(4, 2).std()) if True else [], E_rollstd)
    assert close(fvals(gb[["g", "h"]].skew()) if True else [], E_skew)
    assert close(fvals(gb[["g", "h"]].quantile(0.4)) if True else [], E_quant)
    assert close(fvals(gb[["g", "h"]].sem()) if True else [], E_sem)
test_groupby2()
